mapper.select:
SELECT o.id, o.order_no AS orderNo, o.business_id AS businessId, b.name AS businessName, o.total_amount AS totalAmount, o.paid_amount AS paidAmount, o.paid_quantity AS paidQuantity, o.total_amount - COALESCE(o.paid_amount, 0) AS remainAmount, (SELECT COALESCE(SUM(i.quantity), 0) FROM shipment_item i WHERE i.order_id = o.id AND i.deleted = 0) - COALESCE(o.paid_quantity, 0) AS remainQuantity, o.ship_date AS shipDate, o.remark, o.create_time AS createTime, o.update_time AS updateTime, CASE WHEN o.total_amount IS NULL OR o.total_amount <= 0 THEN 0 WHEN o.paid_amount >= o.total_amount THEN 2 WHEN o.paid_amount > 0 THEN 1 ELSE 0 END AS status, DATEDIFF(CURDATE(), o.ship_date) AS overdueDays FROM shipment_order o LEFT JOIN base_business b ON o.business_id = b.id AND b.deleted = 0 WHERE o.deleted = 0
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND o.business_id = #{businessId}
AND o.ship_date >= #{shipDateStart}
AND o.ship_date <= #{shipDateEnd}
AND (o.paid_amount IS NULL OR o.paid_amount <= 0)
AND o.paid_amount > 0 AND (o.total_amount IS NULL OR o.paid_amount < o.total_amount)
AND o.total_amount > 0 AND o.paid_amount >= o.total_amount
ORDER BY o.create_time ASC, o.id ASC ORDER BY o.ship_date ASC, o.id ASC ORDER BY o.ship_date DESC, o.id DESC ORDER BY o.create_time DESC, o.id DESC

SELECT i.id, i.order_id AS orderId, i.manufacturer_id AS manufacturerId, m.name AS manufacturerName, i.product_id AS productId, p.name AS productName, i.quantity, i.batch_no AS batchNo, i.amount FROM shipment_item i LEFT JOIN base_manufacturer m ON i.manufacturer_id = m.id AND m.deleted = 0 LEFT JOIN base_product p ON i.product_id = p.id AND p.deleted = 0 WHERE i.deleted = 0 AND i.order_id IN
#{orderId}
ORDER BY i.id ASC
